import httpclient, json, strutils, os, asyncdispatch, strformat, times

const
  EXA_API_KEY = getEnv("EXA_API_KEY")
  CEREBRAS_API_KEY = getEnv("CEREBRAS_API_KEY")
  GPT_MODEL = "gpt-oss-120b"
  MAX_TOKENS = 65000
  EXA_RESULTS_LIMIT = 100
  AGENT_CHECK_INTERVAL = 60

type
  SearchResult = object
    id: string
    url: string
    title: string
    text: string
    subpages: seq[SearchResult]
  AgentTask = object
    query: string
    timestamp: Time
    priority: int

var
  taskQueue: seq[AgentTask]
  processedQueries: seq[string]

proc searchExa(query: string): Future[JsonNode] {.async.} =
  let client = newAsyncHttpClient()
  client.headers = newHttpHeaders({
    "x-api-key": EXA_API_KEY,
    "Content-Type": "application/json"
  })
  let body = %*{
    "query": query,
    "type": "auto",
    "num_results": EXA_RESULTS_LIMIT,
    "text": true,
    "subpages": 10,
    "subpageTarget": ["news", "products", "docs", "blog"],
    "livecrawl": "always"
  }
  let response = await client.post("", body = $body)
  result = parseJson(await response.body)
  client.close()

proc chatCompletion(prompt: string): Future[JsonNode] {.async.} =
  let client = newAsyncHttpClient()
  client.headers = newHttpHeaders({
    "Authorization": fmt"Bearer {CEREBRAS_API_KEY}",
    "Content-Type": "application/json"
  })
  let body = %*{
    "model": GPT_MODEL,
    "messages": [
      {"role": "system", "content": "You are an autonomous AI agent with full web search capabilities via Exa API. Generate insightful responses and proactively explore related topics."},
      {"role": "user", "content": prompt}
    ],
    "max_tokens": MAX_TOKENS,
    "stream": false
  }
  let response = await client.post("", body = $body)
  result = parseJson(await response.body)
  client.close()

proc generateResponse(query: string): Future[string] {.async.} =
  let searchResults = await searchExa(query)
  let context = searchResults["results"].pretty()
  let prompt = fmt"Based on the following search results, provide a comprehensive answer to the query: {query}\n\nSearch Results:\n{context}\n\nAdditionally, suggest 3 related topics to explore further."
  let completion = await chatCompletion(prompt)
  result = completion["choices"][0]["message"]["content"].getStr()

proc generateProactiveQueries(response: string): seq[string] =
  let prompt = fmt"Based on this response: {response}\n\nSuggest 3 related queries to explore further."
  let completion = waitFor chatCompletion(prompt)
  let suggestions = completion["choices"][0]["message"]["content"].getStr().split("\n")
  result = suggestions.filterIt(it.len > 0).mapIt(it.strip)

proc scheduleTask(query: string, priority: int = 1) =
  taskQueue.add(AgentTask(query: query, timestamp: now(), priority: priority))

proc processTasks() {.async.} =
  while true:
    if taskQueue.len > 0:
      taskQueue.sort(proc (a, b: AgentTask): int = cmp(b.priority, a.priority))
      let task = taskQueue[0]
      taskQueue.delete(0)
      if task.query notin processedQueries:
        processedQueries.add(task.query)
        let response = await generateResponse(task.query)
        echo fmt"Processed query: {task.query}\nResponse: {response}"
        let newQueries = generateProactiveQueries(response)
        for q in newQueries:
          scheduleTask(q, task.priority - 1)
    await sleepAsync(AGENT_CHECK_INTERVAL * 1000)

proc handleRequest(client: AsyncHttpClient, request: string): Future[string] {.async.} =
  if request.startsWith("GET / "):
    let html = readFile("index.html")
    return html
  elif request.startsWith("GET /search?query="):
    let query = request.split("=")[1].replace("%20", " ")
    scheduleTask(query, 2)
    return "Query scheduled for processing. Check back soon!"
  return "404 Not Found"

proc runWebServer() {.async.} =
  let server = newAsyncHttpClient()
  server.headers = newHttpHeaders({"Content-Type": "text/html"})
  while true:
    let request = await server.acceptRequest()
    let response = await handleRequest(server, request)
    await server.sendResponse(response)

proc autonomousAgent() {.async.} =
  scheduleTask("Latest advancements in AI technology")
  asyncCheck processTasks()
  asyncCheck runWebServer()

when isMainModule:
  asyncCheck autonomousAgent()
  runForever()

